            if datetimes.dt.tz is not None and cutoff.tzinfo is None:
                cutoff = cutoff.tz_localize(datetimes.dt.tz)
            elif datetimes.dt.tz is None and cutoff.tzinfo is not None:
                cutoff = cutoff.tz_localize(None)
